// ============================================================
// Normalize Payload từ soc-server-python & Wazuh SIEM
// Tương thích cả alert có sẵn alert_id và alert RAW từ Wazuh
// ============================================================
const body = $json.body || $json;

function pick(...vals){
  for (const v of vals){ if (v !== undefined && v !== null && v !== '') return v; }
  return null;
}

function extractDomain(url) {
  if (!url) return null;
  try {
    const m = String(url).match(/^[a-zA-Z][a-zA-Z\d+\-.]*:\/\/([^\/:?#]+)/);
    return m ? m[1] : null;
  } catch(e) { return null; }
}

let raw = {};
try {
  raw = typeof body.raw_payload === 'string' ? JSON.parse(body.raw_payload) : (body.raw_payload || {});
} catch(e) { raw = {}; }

const af = (raw && Object.keys(raw).length > 0) ? (raw.all_fields || raw) : (body.all_fields || body);
const rule = af.rule || {};
const agent = af.agent || {};
const data = af.data || {};
const syscheck = af.syscheck || data.syscheck || {};
const win = data.win?.eventdata || {};
const sysmon = data.sysmon?.eventdata || {};

// ---- alert_id từ soc-server nếu đã có ----
const alert_id = body.alert_id || raw.alert_id || '';
const agent_id = pick(body.agent_id, raw.agent_id, agent.id, 'endpoint-win11-01');
const agent_name = pick(body.agent_name, agent.name, 'N/A');

// ---- event_type ----
let event_type = body.event_type
  ?? raw.event_type
  ?? (rule.id !== undefined || rule.level !== undefined ? 'wazuh_alert' : null)
  ?? 'unknown';

// ---- severity ----
const ruleLevel = rule.level;
let severity = (body.severity ?? raw.severity
  ?? (ruleLevel >= 12 ? 'critical' : ruleLevel >= 10 ? 'high' : ruleLevel >= 7 ? 'medium' : ruleLevel !== undefined ? 'low' : 'medium')).toLowerCase();

const severity_num = severity === 'critical' ? 4 : severity === 'high' ? 3 : severity === 'low' ? 1 : 2;

// ---- Network & Target ----
const src_ip = pick(
  raw.src_ip, body.src_ip, body.target,
  data.srcip, win.ipAddress, win.sourceIp, sysmon.sourceIp,
  agent.ip, 'N/A'
);
const original_url = pick(raw.url, body.url, null);
let domain = pick(raw.domain, data.domain, null);
if (!domain && original_url) domain = extractDomain(original_url);

// ---- Process / Endpoint info ----
const process_id = pick(win.processId, sysmon.processId, data.process?.pid, raw.process_id, body.process_id, null);
const command_line = pick(win.commandLine, sysmon.commandLine, data.object?.process?.cmdline, raw.command_line, null);
const file_hash = pick(syscheck.sha256_after, syscheck.sha256, raw.file_hash, null);

// ---- MITRE ATT&CK ----
const mitre = rule.mitre || {};
const mitre_tactic = body.mitre_tactic || (Array.isArray(mitre.tactic) ? mitre.tactic.join(', ') : (mitre.tactic || 'N/A'));
const mitre_id = body.mitre_technique_id || (Array.isArray(mitre.id) ? mitre.id.join(', ') : (mitre.id || 'N/A'));

const description = pick(body.description, raw.description, rule.description, body.attack_type, 'N/A');
const title = body.title || ('[' + event_type.toUpperCase() + '] ' + description);
const timestamp = body.timestamp ?? raw.timestamp ?? $now.toISO();
const reported_by = body.reported_by ?? 'soc-server-python';
const rule_groups = Array.isArray(rule.groups) ? rule.groups : [];
const confidence = body.confidence ?? raw.confidence ?? 'N/A';

// ---- Markdown parsed fields ----
function flattenToMd(obj) {
  const blacklist = ['providerName','providerGuid','version','task','opcode','keywords',
    'eventRecordID','threadID','channel','severityValue','message','level','eventID','systemTime','computer'];
  let result = ''; let count = 0; const MAX = 40;
  function sanitize(v){ return String(v).replace(/`/g, "'").replace(/\n/g, ' ').replace(/\r/g, ' '); }
  function walk(o){
    for (const k in o){
      if (count >= MAX) return;
      if (blacklist.includes(k)) continue;
      const v = o[k];
      if (typeof v === 'object' && v !== null && !Array.isArray(v)) { walk(v); }
      else if (v !== '' && v !== null && v !== undefined) {
        result += '* **' + k + ':** `' + sanitize(v) + '`\n';
        count++;
      }
    }
  }
  walk(obj || {});
  return result || '*(Không có dữ liệu chi tiết)*';
}

const eventDataForFlatten = (data && Object.keys(data).length) ? data
  : (syscheck && Object.keys(syscheck).length) ? syscheck
  : (Object.keys(raw).length ? raw : af);
const parsed_fields_md = flattenToMd(eventDataForFlatten);
const raw_json_md = JSON.stringify(Object.keys(raw).length ? raw : af, null, 2);

return [{ json: {
  alert_id, agent_id, agent_name, event_type, severity, severity_num, title, description,
  src_ip, domain, original_url, process_id, command_line, file_hash,
  mitre_tactic, mitre_id, timestamp,
  rule_id: rule.id ?? 'N/A', rule_level: ruleLevel ?? 'N/A', rule_groups, confidence, reported_by,
  parsed_fields_md, raw_json_md, _raw_body: JSON.stringify(body)
} }];

// Lưu JWT token vào biến chung để gọi các API tiếp theo
const token = $json.token || $json.access_token || '';
const norm = $('Normalize Payload1').item.json;

return [{ json: {
  ...norm,
  _jwt_token: token
} }];

// ============================================================
// Build Threat Intel Summary từ soc-server-python
// Thay thế Cortex VT Analyzer + MISP Check
// ============================================================
const norm = $('Save JWT Token').item.json;
const jwt = norm._jwt_token;

let analyzeResult = {};
try { analyzeResult = $('Analyze IOC (SOC Server)').item.json; } catch(e) {}

let searchResult = {};
try { searchResult = $('Search Indicators DB').item.json; } catch(e) {}

const verdict = analyzeResult.verdict || 'unknown';
const risk_score = analyzeResult.risk_score || 0;
const detections = analyzeResult.detections || 0;
const total_engines = analyzeResult.total_engines || 0;
const ioc_tags = (analyzeResult.tags || []).join(', ');
const ioc_country = analyzeResult.details?.country || 'Unknown';
const community_score = analyzeResult.community_score || 0;
const last_analysis = analyzeResult.last_analysis || 'N/A';

let riskLevel = 'CLEAN';
if (risk_score >= 80) riskLevel = 'CRITICAL';
else if (risk_score >= 60) riskLevel = 'HIGH';
else if (risk_score >= 40) riskLevel = 'MEDIUM';
else if (risk_score > 0) riskLevel = 'LOW';

let ioc_exists = false;
let ioc_id = null;
let ioc_attrs = [];
try {
  const response = searchResult.response || [];
  if (Array.isArray(response) && response.length > 0) {
    ioc_exists = true;
    ioc_id = response[0]?.Event?.id || null;
    ioc_attrs = response[0]?.Event?.Attribute || [];
  }
} catch(e) {}

const ioc_summary_md = `🛡 **Threat Intelligence (SOC Server DB)**\n\n` +
  `### Risk Level: ${riskLevel}\n` +
  `• Verdict: ${verdict}\n` +
  `• Risk Score: ${risk_score}/100\n` +
  `• Detections: ${detections}/${total_engines} engines\n` +
  `• Tags: ${ioc_tags || 'None'}\n` +
  `• Country: ${ioc_country}\n` +
  `• Exists in Blacklist: ${ioc_exists ? 'YES (seen before)' : 'NO (new IOC)'}\n` +
  `• Attributes found: ${ioc_attrs.length}\n` +
  `• Last Analysis: ${last_analysis}`;

return [{ json: {
  ...norm,
  _jwt_token: jwt,
  ioc_verdict: verdict,
  ioc_risk_level: riskLevel,
  ioc_risk_score: risk_score,
  ioc_detections: detections,
  ioc_total_engines: total_engines,
  ioc_tags,
  ioc_country,
  ioc_exists,
  ioc_id,
  ioc_attrs: ioc_attrs.slice(0, 15),
  ioc_summary_md
} }];

