const items = $('Extract Phishing Payload').all();
const payload = (items && items.length > 0) ? items[0].json : {};
const url = payload.url || '';

const match = url.match(/^https?:\/\/([^\/\s:]+)/i);
const domain = match ? match[1] : null;

if (!domain) {
  throw new Error('Không lấy được domain từ URL. Payload nhận được: ' + JSON.stringify(payload));
}

return [{ json: { 
  ...$json, 
  url: payload.url, 
  employee_ip: payload.employee_ip, 
  timestamp: payload.timestamp, 
  domain 
} }];

const dns = $json;
const prev = $('Extract Domain from URL').item.json;
let ips = [];
if (dns.Answer && dns.Answer.length) {
  // Lọc lấy toàn bộ bản ghi A (type === 1)
  ips = dns.Answer.filter(r => r.type === 1).map(a => a.data);
}
return [{ json: { ...prev, resolved_ips: ips } }];

const d = $('Action Switch1').item.json;
const domain = (d.domain || '').toLowerCase().trim();

if (!domain || !/^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?(\.[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?)+$/.test(domain)) {
  throw new Error('Domain không hợp lệ, từ chối gửi SSH: ' + domain);
}

// const FILE = '/var/db/pfblockerng/dnsbl/SOAR_AutoBlock_custom.txt';
const FILE = '/var/unbound/pfb_dnsbl_SOAR.conf';
const SINKHOLE_IP = '192.168.10.1'; // đổi theo IP sinkhole thực tế 

// Escape để tránh domain chứa ký tự lạ làm gãy lệnh shell (dù regex trên đã chặn hầu hết)
const safeDomain = domain.replace(/"/g, '');

const lineA = `local-data: \\"${safeDomain} 60 IN A ${SINKHOLE_IP}\\"`;

const command =
  `grep -q "${safeDomain}" ${FILE} 2>/dev/null || echo "${lineA}" >> ${FILE}; ` +
  `/usr/local/sbin/pfSsh.php playback svc restart unbound`;

return [{ json: { ...d, ssh_command: command } }];

const d = $('Action Switch1').item.json;
const ip = (d.src_ip || '').trim();
const ipv4Regex = /^(\d{1,3}\.){3}\d{1,3}$/;

if (!ipv4Regex.test(ip)) {
  throw new Error('src_ip không hợp lệ, từ chối block: ' + ip);
}

const TABLE = 'SOAR_BlockList';
const command = `pfctl -t ${TABLE} -T add ${ip}`;

return [{ json: { ...d, ssh_command: command } }];

const items = $('Build pfSense DNSBL Command1').all();
const payload = (items && items.length > 0) ? items[0].json : {};

return [{ json: { ...payload, ssh_result: $json } }];

const d = $('Action Switch1').item.json;
const ips = d.resolved_ips || [];
const ipv4Regex = /^(\d{1,3}\.){3}\d{1,3}$/;

// Lọc ra các IP hợp lệ
const validIps = ips.filter(ip => ipv4Regex.test(ip.trim()));

if (validIps.length === 0) {
  return []; // Dừng nhánh này nếu không có IP hợp lệ
}

const TABLE = 'SOAR_Phishing_BlockList';
// Lệnh pfctl hỗ trợ add nhiều IP bằng cách cách nhau bởi khoảng trắng
const command = `pfctl -t ${TABLE} -T add ${validIps.join(' ')}`;

return [{ json: { ...d, ssh_command: command } }];

const ip = ($json.src_ip || '').trim();
const ipv4Regex = /^(\d{1,3}\.){3}\d{1,3}$/;

if (!ipv4Regex.test(ip)) {
  throw new Error('src_ip không hợp lệ, từ chối unblock: ' + ip);
}

const TABLE = 'SOAR_BlockList';
const command = `pfctl -t ${TABLE} -T delete ${ip}`;

return [{ json: { ...$json, ssh_command: command } }];

const items = $('Build pfSense Unblock IP Command1').all();
const payload = (items && items.length > 0) ? items[0].json : {};

return [{ json: { ...payload, ssh_result: $json } }];

